function setCollection(key, focus = false) {
  const d=collections[key];
  if(!d) return;
  $$('.research-tabs [role="tab"]').forEach(button => {
    const selected=button.dataset.collection===key;
    button.setAttribute('aria-selected', String(selected));
    button.tabIndex=selected?0:-1;
    if(selected && focus) button.focus();
  });
  const panel=$('#research-panel');
  panel.dataset.active=key;
  panel.setAttribute('aria-labelledby', 'tab-'+key);
  $('#research-image').src='assets/gallery/'+d.image;
  $('#research-image').alt=d.alt;
  $('#media-caption').textContent=d.caption;
  $('#media-source').href=d.source;
  $('#detail-code').textContent=d.number+' / '+d.label;
  $('#detail-count').textContent=state.loaded?state.papers.filter(p=>p.primaryRole===key).length:d.count;
  $('#detail-title').innerHTML=d.title;
  $('#detail-description').textContent=d.description;
  $('#detail-topics').replaceChildren(...d.topics.map(text => {
    const tag=document.createElement('span'); tag.textContent=text; return tag;
  }));
  $('#detail-example').textContent=d.example;
  $('#collection-link').dataset.browse=key;
  panel.classList.remove('panel-updated');
  requestAnimationFrame(()=>panel.classList.add('panel-updated'));
}

$$('.research-tabs [role="tab"]').forEach(button=>{
  button.addEventListener('click',()=>setCollection(button.dataset.collection));
  button.addEventListener('keydown',event=>{
    const keys=Object.keys(collections);
    const current=keys.indexOf(button.dataset.collection);
    let next;
    if(event.key==='ArrowRight') next=(current+1)%keys.length;
    if(event.key==='ArrowLeft') next=(current+keys.length-1)%keys.length;
    if(event.key==='Home') next=0;
    if(event.key==='End') next=keys.length-1;
    if(next!==undefined){event.preventDefault();setCollection(keys[next],true);}
  });
});

function getFilters(){return {query:ui.search.value.trim(),role:ui.role.value,year:ui.year.value};}
function syncUrl(){
  const {query,role,year}=getFilters();
  const params=new URLSearchParams();
  if(query) params.set('q',query);
  if(role) params.set('collection',role);
  if(year) params.set('year',year);
  const q=params.toString();
  history.replaceState(null,'',location.pathname+(q?'?'+q:'')+location.hash);
}
function paperRow(p){
  const url=safePaperUrl(p.url);
  const title=e(p.title);
  const topics=(p.topics||[]).slice(0,2).map(t=>'<span class="topic">'+e(t.replaceAll('-',' '))+'</span>').join('');
  const venue=p.venue && !p.venue.includes('listed venue')?p.venue:(p.venue||'').split(' / ')[0];
  const link=url?'<a class="paper-title" href="'+e(url)+'" target="_blank" rel="noopener noreferrer">'+title+'</a>':'<span class="paper-title">'+title+'</span>';
  return '<article class="paper-row"><span class="paper-year">'+e(p.year)+'</span><div class="paper-main">'+link+'<div class="paper-meta"><span class="venue">'+e(venue)+'</span><span>'+e(ROLES[p.primaryRole]||'Research')+'</span>'+topics+'</div></div>'+(url?'<a class="paper-link" href="'+e(url)+'" target="_blank" rel="noopener noreferrer" aria-label="Open '+title+'"><svg class="icon"><use href="#i-north"/></svg></a>':'')+'</article>';
}
function render({reset=false,updateUrl=true}={}){
  if(!state.loaded) return;
  if(reset) state.visible=pageSize;
  const filters=getFilters();
  const matches=searchPapers(state.papers,filters);
  ui.list.innerHTML=matches.slice(0,state.visible).map(paperRow).join('');
  ui.status.textContent=matches.length+' '+(matches.length===1?'work':'works')+(filters.role?' · '+ROLES[filters.role]:' in the collection');
  ui.empty.hidden=matches.length>0;
  ui.more.hidden=matches.length<=state.visible;
  if(!ui.more.hidden) ui.more.innerHTML='Show '+Math.min(pageSize,matches.length-state.visible)+' more papers <span aria-hidden="true">↓</span>';
  $$('.filter-button').forEach(button=>{
    const active=button.dataset.filter===filters.role;
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',String(active));
  });
  if(updateUrl) syncUrl();
}
function setRole(role){
  if(!state.loaded) return;
  ui.role.value=Object.hasOwn(ROLES,role)?role:'';
  render({reset:true});
}
function resetFilters(){
  ui.search.value='';ui.role.value='';ui.year.value='';
  render({reset:true});ui.search.focus({preventScroll:true});
}
function restoreFilters(){
  const p=new URLSearchParams(location.search);
  ui.search.value=p.get('q')||'';
  ui.role.value=Object.hasOwn(ROLES,p.get('collection'))?p.get('collection'):'';
  ui.year.value=[...ui.year.options].some(o=>o.value===p.get('year'))?p.get('year'):'';
}
function populate(){
  for(const [key,label] of Object.entries(ROLES)){
    const option=new Option(label,key);ui.role.add(option);
    const n=state.papers.filter(p=>p.primaryRole===key).length;
    $$('[data-count="'+key+'"]').forEach(el=>{el.textContent=n;});
  }
  [...new Set(state.papers.map(p=>p.year))].filter(Boolean).sort((a,b)=>b-a).forEach(year=>ui.year.add(new Option(year,String(year))));
  $('#paper-count').textContent=state.papers.length;
  $('.filter-button[data-filter=""] b').textContent=state.papers.length;
}
async function load(){
  try{
    const response=await fetch('data/papers.json');
    if(!response.ok) throw Error('Catalog unavailable');
    const data=await response.json();
    if(!Array.isArray(data.papers)) throw Error('Catalog format invalid');
    state.papers=sortPapers(data.papers.filter(p=>p.status!=='context'));
    state.loaded=true;populate();restoreFilters();render({updateUrl:false});
  }catch(error){
    ui.status.textContent='The collection could not be loaded.';
    ui.list.innerHTML='<div class="empty-state"><h3>The reading list is still available.</h3><p>Open the <a href="https://github.com/Eurekaleo/awesome-ai-for-games#contents">complete GitHub collection</a> to browse every paper.</p><button type="button" class="button load-more" id="retry-catalog">Try again</button></div>';
    $('#retry-catalog').addEventListener('click',()=>{ui.list.textContent='';ui.status.textContent='Loading papers…';load();});
  }
}
ui.search.addEventListener('input',()=>render({reset:true}));
ui.year.addEventListener('change',()=>render({reset:true}));
ui.role.addEventListener('change',()=>render({reset:true}));
$('#clear-filters').addEventListener('click',resetFilters);
ui.more.addEventListener('click',()=>{
  const firstNew=state.visible;state.visible+=pageSize;render();
  const next=$$('.paper-title')[firstNew];next?.focus({preventScroll:true});
});
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>setRole(button.dataset.filter)));
$('#collection-link').addEventListener('click',event=>{
  ui.search.value='';ui.year.value='';setRole(event.currentTarget.dataset.browse);
});
window.addEventListener('popstate',()=>{restoreFilters();render({reset:true,updateUrl:false});});
const header=$('.site-header');
let tick=false;
window.addEventListener('scroll',()=>{if(!tick){tick=true;requestAnimationFrame(()=>{header.classList.toggle('is-scrolled',window.scrollY>85);tick=false;});}},{passive:true});
const menu=$('#menu-toggle'), menuPanel=$('#mobile-nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menuPanel.hidden=true;}
menu.addEventListener('click',()=>{
  const open=menu.getAttribute('aria-expanded')!=='true';
  menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');menuPanel.hidden=!open;
});
$$('#mobile-nav a').forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!menuPanel.hidden){closeMenu();menu.focus();}});
window.matchMedia('(min-width:601px)').addEventListener('change',event=>{if(event.matches) closeMenu();});
load();
